"""Security tests for shell_exec — metacharacter evasion detection."""

import pytest
from fim_one.core.tool.builtin.shell_exec import _check_shell_metacharacters


class TestMetacharEvasion:
    """Tests for _check_shell_metacharacters."""

    # --- Safe commands should pass ---

    def test_safe_echo(self):
        assert _check_shell_metacharacters("echo hello") is None

    def test_safe_ls(self):
        assert _check_shell_metacharacters("ls -la") is None

    def test_safe_pipe(self):
        assert _check_shell_metacharacters("cat file | sort | uniq") is None

    def test_safe_redirect(self):
        assert _check_shell_metacharacters("echo hello > output.txt") is None

    def test_safe_jq(self):
        assert _check_shell_metacharacters("jq '.name' data.json") is None

    def test_safe_quoted_string(self):
        assert _check_shell_metacharacters('echo "hello world"') is None

    def test_safe_semicolon(self):
        assert _check_shell_metacharacters("ls; pwd") is None

    def test_safe_exit_code(self):
        """$? should NOT be blocked (digit, not [A-Za-z_])."""
        assert _check_shell_metacharacters("echo $?") is None

    def test_safe_positional_params(self):
        """$1, $2 should NOT be blocked (digits)."""
        assert _check_shell_metacharacters("echo $1 $2") is None

    # --- Evasion patterns should be blocked ---

    def test_blocked_command_substitution(self):
        result = _check_shell_metacharacters("$(whoami)")
        assert result is not None
        assert "$(" in result

    def test_blocked_backtick(self):
        result = _check_shell_metacharacters("`whoami`")
        assert result is not None
        assert "backtick" in result

    def test_blocked_empty_double_quote(self):
        result = _check_shell_metacharacters('su""do ls')
        assert result is not None
        assert "empty quote" in result

    def test_blocked_empty_single_quote(self):
        result = _check_shell_metacharacters("su''do ls")
        assert result is not None
        assert "empty quote" in result

    def test_blocked_variable_ref(self):
        result = _check_shell_metacharacters("$SHELL")
        assert result is not None
        assert "variable reference" in result

    def test_blocked_variable_assignment_ref(self):
        result = _check_shell_metacharacters("c=curl; $c evil.com")
        assert result is not None

    def test_blocked_variable_expansion(self):
        result = _check_shell_metacharacters("${HOME}/bin/bash")
        assert result is not None
        assert "${}" in result

    def test_blocked_base64_decode(self):
        result = _check_shell_metacharacters("echo YmFzaA== | base64 -d")
        assert result is not None
        assert "base64" in result

    def test_blocked_base64_decode_long(self):
        result = _check_shell_metacharacters("base64 --decode payload.txt")
        assert result is not None

"""Regression tests for ConnectorToolAdapter._inject_auth credential resolution.

Guards against field-name drift between the encrypted credential blob
(``default_token``/``default_api_key``/``default_username``/``default_password``)
and the adapter's lookup logic.  Historical bug: adapter read ``creds["token"]``
while the blob stored the value under ``default_token``, producing an empty
``Authorization`` header and surprise 401s from the target service.
"""

from __future__ import annotations

from typing import Any

import pytest

from fim_one.core.tool.connector.adapter import ConnectorToolAdapter


def _make_adapter(
    auth_type: str,
    auth_config: dict[str, Any] | None,
    auth_credentials: dict[str, str] | None,
) -> ConnectorToolAdapter:
    return ConnectorToolAdapter(
        connector_name="github",
        connector_base_url="https://api.example.com",
        connector_auth_type=auth_type,
        connector_auth_config=auth_config,
        action_name="list_repos",
        action_description="list",
        action_method="GET",
        action_path="/user/repos",
        action_parameters_schema=None,
        action_request_body_template=None,
        action_response_extract=None,
        action_requires_confirmation=False,
        auth_credentials=auth_credentials,
    )


class TestBearerAuthInjection:
    def test_reads_default_token_from_decrypted_creds(self) -> None:
        adapter = _make_adapter(
            auth_type="bearer",
            auth_config={"token_prefix": "Bearer"},
            auth_credentials={"default_token": "[REDACTED]"},
        )
        headers: dict[str, str] = {}
        adapter._inject_auth(headers)
        assert headers["Authorization"] == "Bearer ghp_secret_abc"

    def test_legacy_token_key_still_honoured(self) -> None:
        adapter = _make_adapter(
            auth_type="bearer",
            auth_config={"token_prefix": "Bearer"},
            auth_credentials={"token": "legacy_xyz"},
        )
        headers: dict[str, str] = {}
        adapter._inject_auth(headers)
        assert headers["Authorization"] == "Bearer legacy_xyz"

    def test_auth_config_fallback_when_creds_empty(self) -> None:
        adapter = _make_adapter(
            auth_type="bearer",
            auth_config={"token_prefix": "Bearer", "default_token": "config_tok"},
            auth_credentials={},
        )
        headers: dict[str, str] = {}
        adapter._inject_auth(headers)
        assert headers["Authorization"] == "Bearer config_tok"

    def test_no_header_when_all_sources_empty(
        self, caplog: pytest.LogCaptureFixture
    ) -> None:
        adapter = _make_adapter(
            auth_type="bearer",
            auth_config={"token_prefix": "Bearer"},
            auth_credentials={},
        )
        headers: dict[str, str] = {}
        with caplog.at_level("WARNING"):
            adapter._inject_auth(headers)
        assert "Authorization" not in headers
        assert any(
            "no resolvable token" in rec.message for rec in caplog.records
        ), "missing token should emit a WARNING so this failure mode is not silent"

    def test_custom_prefix_respected(self) -> None:
        adapter = _make_adapter(
            auth_type="bearer",
            auth_config={"token_prefix": "token"},
            auth_credentials={"default_token": "ghp_x"},
        )
        headers: dict[str, str] = {}
        adapter._inject_auth(headers)
        assert headers["Authorization"] == "token ghp_x"


